/* style.css */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600&family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap');

:root {
  --bg-color: #F5F2ED;
  --text-color: #1A1A1A;
  --text-muted: #555555;
  --accent-color: #D37D64; /* terracotta */
  --font-serif: 'Playfair Display', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  font-family: var(--font-sans);
  line-height: 1.6;
  font-size: 16px;
  font-weight: 400;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 500;
  line-height: 1.1;
  color: var(--text-color);
}

a {
  color: inherit;
  text-decoration: none;
  transition: opacity 0.2s ease;
}

a:hover {
  opacity: 0.6;
}

/* Header & Nav */
header {
  padding: 2rem 4vw;
  display: flex;
  justify-content: space-between;
  align-items: center;
  position: relative;
  z-index: 1000;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.nav-desktop {
  display: none;
}

.nav-desktop a {
  margin-left: 2.5rem;
  font-size: 0.95rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

@media (min-width: 768px) {
  .nav-desktop {
    display: flex;
  }
  .menu-toggle {
    display: none;
  }
}

.menu-toggle {
  background: none;
  border: none;
  cursor: pointer;
  z-index: 1001;
  position: relative;
  width: 30px;
  height: 20px;
}

.hamburger-line {
  display: block;
  width: 100%;
  height: 2px;
  background-color: var(--text-color);
  position: absolute;
  left: 0;
  transition: transform 0.3s ease, opacity 0.3s ease;
}

.hamburger-line:nth-child(1) { top: 0; }
.hamburger-line:nth-child(2) { top: 9px; }
.hamburger-line:nth-child(3) { top: 18px; }

.menu-open .hamburger-line:nth-child(1) {
  transform: translateY(9px) rotate(45deg);
}
.menu-open .hamburger-line:nth-child(2) {
  opacity: 0;
}
.menu-open .hamburger-line:nth-child(3) {
  transform: translateY(-9px) rotate(-45deg);
}

/* Mobile Overlay */
.nav-mobile {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background-color: var(--bg-color);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  z-index: 900;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.nav-mobile.active {
  opacity: 1;
  pointer-events: auto;
}

.nav-mobile a {
  font-family: var(--font-serif);
  font-size: 3rem;
  margin: 1.5rem 0;
  font-weight: 500;
}

/* Hero Section */
.hero {
  padding: 8vw 4vw;
  min-height: 60vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.hero h1 {
  font-size: clamp(3rem, 7vw, 6rem);
  max-width: 22ch;
  margin-bottom: 4rem;
  letter-spacing: -0.02em;
}

/* Media Showcase */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  margin-top: 2rem;
}

@media (min-width: 768px) {
  .media-showcase {
    grid-template-columns: repeat(3, 1fr);
  }
}

.media-block {
  aspect-ratio: 3/4;
  background-color: var(--accent-color);
  border-radius: 4px;
}
.media-block:nth-child(2) {
  background-color: #A3B19B; /* sage */
}
.media-block:nth-child(3) {
  background-color: #DBCDBA; /* sand */
}

/* Marquee */
.marquee-section {
  padding: 6rem 0;
  overflow: hidden;
  background-color: var(--bg-color);
}

.marquee-row {
  display: flex;
  width: max-content;
  white-space: nowrap;
  font-family: var(--font-sans);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 300;
  margin-bottom: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-color);
}

.marquee-content {
  display: flex;
  padding-left: 2rem;
  gap: 2rem;
}

.marquee-content span {
  display: inline-block;
}

.marquee-left {
  animation: marquee-left 40s linear infinite;
}
.marquee-right {
  animation: marquee-right 40s linear infinite;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* About Section */
.about-section {
  padding: 8rem 4vw;
  max-width: 1100px;
  margin: 0 auto;
}

.about-section h2 {
  font-family: var(--font-sans);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 3rem;
  color: var(--text-muted);
}

.about-section p {
  font-size: clamp(1.5rem, 3.5vw, 2.5rem);
  font-family: var(--font-serif);
  line-height: 1.4;
  margin-bottom: 2rem;
}

/* Editorial (Founder Letter) */
.editorial-section {
  padding: 6rem 4vw 10rem;
  max-width: 800px;
  margin: 0 auto;
}

.editorial-section h1 {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  margin-bottom: 4rem;
}

.editorial-section p {
  font-size: 1.15rem;
  line-height: 1.8;
  margin-bottom: 2rem;
  color: #2A2A2A;
}

/* Services */
.services-intro {
  padding: 6rem 4vw;
  max-width: 1000px;
  margin: 0 auto;
}

.services-intro h1 {
  font-size: clamp(3rem, 6vw, 5rem);
  margin-bottom: 2rem;
}

.services-intro p {
  font-size: 1.5rem;
  font-family: var(--font-serif);
  line-height: 1.5;
  margin-bottom: 2rem;
}

.divider {
  height: 1px;
  background-color: rgba(0,0,0,0.1);
  margin: 4rem 4vw;
}

.services-list {
  padding: 2rem 4vw 8rem;
  max-width: 1000px;
  margin: 0 auto;
}

.services-list > h2 {
  font-family: var(--font-sans);
  font-size: 1.25rem;
  margin-bottom: 5rem;
  font-weight: 500;
}

.service-item {
  margin-bottom: 5rem;
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
}

@media (min-width: 768px) {
  .service-item {
    grid-template-columns: 300px 1fr;
    gap: 4rem;
  }
}

.service-item h3 {
  font-size: 2.5rem;
  margin-bottom: 1rem;
}

.service-item p {
  font-size: 1.15rem;
  line-height: 1.7;
  color: #2A2A2A;
}

/* Clients Grid */
.clients-header {
  padding: 6rem 4vw 2rem;
  max-width: 1400px;
  margin: 0 auto;
}

.clients-header h1 {
  font-size: clamp(3rem, 6vw, 5rem);
}

.clients-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 4rem 2rem;
  padding: 2rem 4vw 8rem;
  max-width: 1400px;
  margin: 0 auto;
}

@media (min-width: 768px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .clients-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.client-item {
  border-top: 1px solid rgba(0,0,0,0.1);
  padding-top: 1.5rem;
}

.client-item h3 {
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.client-item p {
  font-size: 0.95rem;
  line-height: 1.6;
  color: var(--text-muted);
}

/* Contact */
.contact-section {
  min-height: calc(100vh - 100px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 4vw;
  text-align: center;
}

.contact-hero {
  font-size: clamp(4rem, 15vw, 12rem);
  font-weight: 400;
  margin-bottom: 6rem;
  line-height: 1;
  letter-spacing: -0.03em;
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

@media (min-width: 768px) {
  .contact-links {
    flex-direction: row;
    gap: 5rem;
  }
}

.contact-links a {
  font-size: 1.75rem;
  font-family: var(--font-sans);
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Footer */
footer {
  padding: 4rem 4vw;
  text-align: center;
  font-size: 0.85rem;
  color: var(--text-muted);
  border-top: 1px solid rgba(0,0,0,0.05);
  font-family: var(--font-sans);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

/* script.js */
document.addEventListener('DOMContentLoaded', () => {
  // Mobile Nav Toggle
  const menuToggle = document.querySelector('.menu-toggle');
  const navMobile = document.querySelector('.nav-mobile');

  if (menuToggle && navMobile) {
    menuToggle.addEventListener('click', () => {
      menuToggle.classList.toggle('menu-open');
      navMobile.classList.toggle('active');

      if (navMobile.classList.contains('active')) {
        document.body.style.overflow = 'hidden';
      } else {
        document.body.style.overflow = '';
      }
    });
  }

  // Clone marquee content for smooth infinite scrolling
  const marqueeRows = document.querySelectorAll('.marquee-row');
  marqueeRows.forEach(row => {
    const content = row.querySelector('.marquee-content');
    if (content) {
      // Clone it to make it twice as long for continuous looping
      const clone = content.cloneNode(true);
      row.appendChild(clone);
    }
  });
});
